"""Draft quizzes generated by AI from a material.

The API Lambda cannot reach Bedrock, so generation is a queue: the tutor asks
for it, the AI worker (outside the VPC, the same Lambda as the grader) claims
the job, downloads the material through a short-lived link, asks Claude and
posts a quiz back. The quiz is saved as a draft for the tutor to review.
"""

import uuid
from dataclasses import dataclass
from datetime import timedelta

from pydantic import ValidationError
from sqlalchemy import func, or_, select
from sqlalchemy.orm import Session

from app.models import GenerationStatus, QuizGeneration, QuizStatus
from app.schemas.quiz import QuizIn
from app.services import clock, materials, quizzes
from app.services.errors import Conflict, Invalid, NotFound
from app.storage import Storage

LEASE = timedelta(minutes=5)
# A tutor cannot queue more than this many paid generations at once.
MAX_PENDING_PER_TUTOR = 3


@dataclass(frozen=True)
class GenerationTask:
    job_id: uuid.UUID
    material_title: str
    content_type: str
    download_url: str
    question_count: int
    include_written: bool
    instructions: str | None


def request(
    session: Session,
    tutor_id: uuid.UUID,
    material_id: uuid.UUID,
    *,
    question_count: int,
    include_written: bool,
    instructions: str | None,
) -> QuizGeneration:
    materials.get_owned(session, tutor_id, material_id)
    pending = session.scalar(
        select(func.count())
        .select_from(QuizGeneration)
        .where(
            QuizGeneration.tutor_id == tutor_id,
            QuizGeneration.status == GenerationStatus.pending,
        )
    )
    if pending >= MAX_PENDING_PER_TUTOR:
        raise Conflict("too_many_generations")
    job = QuizGeneration(
        tutor_id=tutor_id,
        material_id=material_id,
        status=GenerationStatus.pending,
        question_count=question_count,
        include_written=include_written,
        instructions=instructions,
    )
    session.add(job)
    session.commit()
    return job


def list_jobs(session: Session, tutor_id: uuid.UUID) -> list[QuizGeneration]:
    return list(
        session.scalars(
            select(QuizGeneration)
            .where(QuizGeneration.tutor_id == tutor_id)
            .order_by(QuizGeneration.created_at.desc())
            .limit(50)
        )
    )


def get_job(session: Session, tutor_id: uuid.UUID, job_id: uuid.UUID) -> QuizGeneration:
    job = session.scalar(
        select(QuizGeneration).where(
            QuizGeneration.id == job_id, QuizGeneration.tutor_id == tutor_id
        )
    )
    if job is None:
        raise NotFound
    return job


# ---------- the AI worker (/api/internal/generation) ----------


def claim(session: Session, storage: Storage, limit: int) -> list[GenerationTask]:
    now = clock.now()
    jobs = (
        session.scalars(
            select(QuizGeneration)
            .where(
                QuizGeneration.status == GenerationStatus.pending,
                or_(
                    QuizGeneration.claimed_at.is_(None),
                    QuizGeneration.claimed_at < now - LEASE,
                ),
            )
            .order_by(QuizGeneration.created_at)
            .limit(limit)
            .with_for_update(skip_locked=True, of=QuizGeneration)
        )
        .unique()
        .all()
    )
    tasks = []
    for job in jobs:
        if job.material is None:  # deleted meanwhile
            job.status, job.error, job.finished_at = (
                GenerationStatus.failed,
                "material_deleted",
                now,
            )
            continue
        job.claimed_at = now
        tasks.append(
            GenerationTask(
                job_id=job.id,
                material_title=job.material.title,
                content_type=job.material.content_type,
                download_url=storage.presign_download(job.material.storage_key),
                question_count=job.question_count,
                include_written=job.include_written,
                instructions=job.instructions,
            )
        )
    session.commit()
    return tasks


def _pending(session: Session, job_id: uuid.UUID) -> QuizGeneration:
    job = session.scalar(
        select(QuizGeneration)
        .where(QuizGeneration.id == job_id)
        .with_for_update(of=QuizGeneration)
    )
    if job is None or job.status != GenerationStatus.pending:
        raise NotFound("not_waiting_for_generator")
    return job


def apply_result(
    session: Session, job_id: uuid.UUID, quiz_data: dict
) -> QuizGeneration:
    """Validate the generated quiz like a tutor's own and save it as a draft."""
    job = _pending(session, job_id)
    try:
        data = QuizIn.model_validate(quiz_data)
    except ValidationError:
        job.status, job.error, job.finished_at = (
            GenerationStatus.failed,
            "invalid_quiz",
            clock.now(),
        )
        session.commit()
        raise Invalid("invalid_quiz") from None
    quiz = quizzes.create_quiz(
        session,
        job.tutor_id,
        data,
        status=QuizStatus.draft,
        source_material_id=job.material_id,
    )
    job.status, job.quiz_id, job.finished_at = (
        GenerationStatus.done,
        quiz.id,
        clock.now(),
    )
    session.commit()
    return job


def fail(session: Session, job_id: uuid.UUID, reason: str) -> QuizGeneration:
    job = _pending(session, job_id)
    job.status, job.error, job.finished_at = (
        GenerationStatus.failed,
        reason[:200] or "failed",
        clock.now(),
    )
    session.commit()
    return job
